function respostaJson(dados, status = 200) {
  return new Response(JSON.stringify(dados), {
    status,
    headers: {
      "Content-Type": "application/json; charset=UTF-8",
      "Cache-Control": "no-store",
    },
  });
}

function normalizarEmail(email) {
  return String(email || "").trim().toLowerCase();
}

function emailValido(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function gerarCodigo() {
  const numeros = new Uint32Array(1);
  crypto.getRandomValues(numeros);

  return String(100000 + (numeros[0] % 900000));
}

async function gerarHash(texto) {
  const dados = new TextEncoder().encode(texto);
  const hash = await crypto.subtle.digest("SHA-256", dados);

  return Array.from(new Uint8Array(hash))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

export async function onRequestPost(context) {
  try {
    const { request, env } = context;

    let corpo;

    try {
      corpo = await request.json();
    } catch {
      return respostaJson(
        {
          sucesso: false,
          mensagem: "Dados enviados em formato inválido.",
        },
        400
      );
    }

    const email = normalizarEmail(corpo.email);

    if (!email) {
      return respostaJson(
        {
          sucesso: false,
          mensagem: "Informe o e-mail.",
        },
        400
      );
    }

    if (!emailValido(email)) {
      return respostaJson(
        {
          sucesso: false,
          mensagem: "Informe um e-mail válido.",
        },
        400
      );
    }

    const pet = await env.DB.prepare(
      `
      SELECT id, nome, nome_tutor, email
      FROM pets
      WHERE LOWER(email) = ?
      LIMIT 1
      `
    )
      .bind(email)
      .first();

    if (!pet) {
      return respostaJson(
        {
          sucesso: false,
          mensagem: "Nenhuma conta foi encontrada com esse e-mail.",
        },
        404
      );
    }

    const agora = new Date();
    const expiraEm = new Date(agora.getTime() + 10 * 60 * 1000);

    const codigo = gerarCodigo();
    const codigoHash = await gerarHash(codigo);

    const ip =
      request.headers.get("CF-Connecting-IP") ||
      request.headers.get("X-Forwarded-For") ||
      null;

    await env.DB.prepare(
      `
      UPDATE codigos_login
      SET usado = 1
      WHERE email = ?
        AND usado = 0
      `
    )
      .bind(email)
      .run();

    await env.DB.prepare(
      `
      INSERT INTO codigos_login (
        email,
        codigo_hash,
        criado_em,
        expira_em,
        usado,
        tentativas,
        ip
      )
      VALUES (?, ?, ?, ?, 0, 0, ?)
      `
    )
      .bind(
        email,
        codigoHash,
        agora.toISOString(),
        expiraEm.toISOString(),
        ip
      )
      .run();

    console.log("======================================");
    console.log("CÓDIGO DE LOGIN ORBITEK PETS");
    console.log(`E-mail: ${email}`);
    console.log(`Código: ${codigo}`);
    console.log(`Expira em: ${expiraEm.toISOString()}`);
    console.log("======================================");

    return respostaJson({
      sucesso: true,
      mensagem: "Código de acesso gerado com sucesso.",
      expiraEm: expiraEm.toISOString(),

      // Somente para desenvolvimento.
      codigoDesenvolvimento: codigo,
    });
  } catch (erro) {
    console.error("Erro ao solicitar login:", erro);

    return respostaJson(
      {
        sucesso: false,
        mensagem: "Não foi possível gerar o código de acesso.",
      },
      500
    );
  }
}

export function onRequestGet() {
  return respostaJson(
    {
      sucesso: false,
      mensagem: "Método não permitido.",
    },
    405
  );
}